  compat_emergencies_title:{ en: "Emergency transfusion rules", bn: "জরুরি ট্রান্সফিউশনের নিয়ম", ar: "قواعد نقل الدم في الطوارئ" },
  compat_did_you_know:{ en: "Did you know",   bn: "জানেন কি",                  ar: "هل تعلم" },
  compat_want_help:{ en: "Want to help?",     bn: "সাহায্য করতে চান?",          ar: "هل تريد المساعدة؟" },
  compat_help_lead:{ en: "O− red cells and AB plasma are the two scarcest products in Bangladesh. Register as a regular donor and keep your availability switched on.", bn: "O− লোহিত কণিকা আর AB প্লাজমা — বাংলাদেশের সবচেয়ে দুর্লভ দুটি উপাদান। নিয়মিত দাতা হিসেবে নিবন্ধন করুন।", ar: "كريات O− وبلازما AB هما أندر مكونين في بنغلاديش. سجّل كمتبرع منتظم وحافظ على توفرك." },

  // ---------- educational resources ----------
  res_library:     { en: "Library",           bn: "লাইব্রেরি",                 ar: "المكتبة" },
  res_lead:        { en: "Complete guides to donation, compatibility, emergency first aid and donor health — every article is a full read, not a teaser.", bn: "রক্তদান, সামঞ্জস্যতা, জরুরি প্রাথমিক চিকিৎসা ও দাতার স্বাস্থ্য নিয়ে পূর্ণাঙ্গ গাইড — প্রতিটি আর্টিকেল সম্পূর্ণ।", ar: "أدلة شاملة عن التبرع والتوافق والإسعافات الأولية وصحة المتبرع — مقالات كاملة وليست ملخصات." },
  res_load_error:  { en: "Live data unavailable — showing the built-in library.", bn: "লাইভ ডেটা লোড করা যায়নি — বিল্ট-ইন লাইব্রেরি দেখানো হচ্ছে।", ar: "تعذّر تحميل البيانات المباشرة — تُعرض المكتبة المدمجة." },
