  res_search_ph:   { en: "Search a topic… e.g. iron, dengue, thalassaemia", bn: "বিষয় খুঁজুন… যেমন: আয়রন, ডেঙ্গু, থ্যালাসেমিয়া", ar: "ابحث عن موضوع… مثل: الحديد، حمى الضنك، الثلاسيميا" },
